VERSION = "2.0.0"
from dataclasses import dataclass

@dataclass
class App:
    name: str

    def greet(self) -> str:
        return f"Hello from {self.name}!"

    def farewell(self) -> str:
        return f"{self.name} signing off."

def main():
    app = App("Demo")
    print(app.greet())
    print(app.farewell())
